    if (p.held_up) chips.push(`holds up ${plural(p.held_up, 'ticket')}${p.on_path ? `, ${p.on_path} on the critical path` : ''}${p.behind ? `, ${p.behind} more behind ${p.held_up > 1 ? 'them' : 'it'}` : ''}`);
