  if (rid && rid !== 'home' && !LINK_KINDS[ownEntry(loadSettings().links, rid)?.kind]?.hostsComponents) die(`--repo ${rid}: not a repo link (devteam.mjs links)`);
  if (cls === 'improvement-trial') upkeepAllows('a new trial');
