    detail: flagStr('detail') ?? die('observe needs --detail'), detector: flagStr('detector'), severity: flagNum('severity'), valence: flagNum('valence'),
    source_key: flagStr('key'), refs: asList(flags.refs), fix_hint: flagStr('fix'),
