    if (m.source === 'owner' && by !== 'owner') die(`${id} is the owner's yes: ask a goal-met question (ask --class goal-met --goal ${id} --question "${m.question}" --recommendation yes), then goal reading ${id} --approved <qid>`);
    const v = flagNum('value');
