  const hit = cache.data[f];
  if (hit && hit.size === st.size && hit.mtime === st.mtimeMs && hit.v === USAGE_PARSE_V) return hit;
  let v;
  try { v = parse(fs.readFileSync(f, 'utf8')); } catch { v = { byCwd: {} }; }
