    // has already said its alerts
    if (flags.json) { json({ polled: res.map((r) => r.name), alerts }); if (res.length) suspectEscapes(); return; }
    if (!res.length) return out(all.length ? 'nothing due' : 'no sensors (settings: sensors)');
